parameter.description:
partyId, personName, preferredName, organizationPartyId,
                organizationName, jobTitle, managerPartyId, managerName, workEmail, workPhone, workLocation, state, stateText;
                for an HR reader partyRelationshipId, fromDate, thruDate, fromDateText, thruDateText, terminationReason

actions.script:
try {
    const task = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).disableAuthz().one()
    if (task == null) return
    const userIds = Array.from(ec.entity.find('moqui.security.UserAccount').condition('partyId', partyId).selectField('userId')
            .disableAuthz().list()).map((account) => account.userId).filter((userId) => userId !== ec.user.userId)
    if (!userIds.length) return
    const me = ec.user.userAccount?.partyId ? ec.entity.find('mantle.party.Person').condition('partyId', ec.user.userAccount.partyId)
            .disableAuthz().one() : null
    const assignedByName = (me ? [me.firstName, me.lastName].filter((part) => part).join(' ') : '') || ec.user.username || 'People'
    const due = task.estimatedCompletionDate
    const dueDateText = due ? ec.l10n.format(new Date(Number(String(due)) || Date.parse(String(due))), 'MMM d') : 'when you can'
    // to the assignee alone (directOnly): a People task may be a protected checklist step or a confidential case's
    // (People follow-up 1)
    ec.makeNotificationMessage().topic('PeopleTaskAssigned').userIds(userIds)
            .message({workEffortId: workEffortId, assignedByName: assignedByName, dueDateText: dueDateText})
            .record('mantle.work.effort.WorkEffort', workEffortId).directOnly().send()
} catch (err) {
    ec.logger.error(`People task ${workEffortId} assigned to ${partyId}: notification not sent: ${err && err.message ? err.message : err}`)
}
